import{_ as n,l as r,o as e,c as s,v as t,p as l,x as o,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Kimi K3","description":"","frontmatter":{"title":"Kimi K3","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kimi-k3.md","filePath":"llm/kimi-k3.md","lastUpdated":1789023840000}'),A={name:"llm/kimi-k3.md"};function K(h,a,c,E,g,M){const i=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="kimi-k3" tabindex="-1">Kimi K3 <a class="header-anchor" href="#kimi-k3" aria-label="Permalink to &quot;Kimi K3&quot;">​</a></h1><div class="epigraph"><p>K3 把预训练底座扩到 3T 量级，同时把强化学习、推理力度与百万上下文上的长程交互一起拉到开源前沿；整体仍落后最强闭源旗舰，但在评测套件里稳定超过其它对照。</p><footer>—— Kimi Team，Kimi K3: Open Frontier Intelligence，arXiv:2607.24653</footer></div><p><a href="/llm/kimi-k2">Kimi K2</a> 是约 1.04T / 32B 激活的非思考 MoE，主场是工具与 SWE。<a href="/llm/kimi-k15">k1.5</a> 是可拉长的思考模型。2026 年 7 月 16 日的 <strong>Kimi K3</strong> 把两条轴一起做：总参 <strong>2.8T</strong>、激活 <strong>104B</strong>，原生视觉，上下文 <strong>1,048,576</strong> token，并开放权重。技术博客与随后的报告（arXiv:2607.24653）把结构差分写在 <strong>Kimi Delta Attention（KDA）</strong>、<strong>Attention Residuals（AttnRes）</strong> 与 <strong>Stable LatentMoE</strong> 上，相对 K2 宣称大约 <strong>2.5×</strong> 的标度效率。本篇按博客、GitHub 规格表与报告摘要写可核对的设计，不把未写入这些文本的数据配比编成语料表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开源侧在测试时计算（思考、智能体环）上追得很快，预训练规模却长期停在 1T 上下。只加 RL 不加大底座，会与最强闭源系统拉开「先验容量」差距。K3 要同时做：把 MoE 拉到近 3T、把上下文拉到 1M、把视觉收进同一套权重，并且在超稀疏路由下还能训稳。K2 的 MLA + MuonClip 已经证明万亿可训；再往上，序列维的二次注意力与深度上的残差累积都会变成一等瓶颈。</p><p>后训练的缺口是长地平线：内核优化、编译器、芯片设计、跨论文复现，轨迹以小时计、工具调用以千次计。若思考历史在多轮里被 harness 丢掉，生成会不稳定——这是训练制度，不是「换个系统提示」能补的。</p><h3 id="规格表-2-8t-104b-896-选-16" tabindex="-1">规格表：2.8T / 104B，896 选 16 <a class="header-anchor" href="#规格表-2-8t-104b-896-选-16" aria-label="Permalink to &quot;规格表：2.8T / 104B，896 选 16&quot;">​</a></h3><p>GitHub 模型卡与报告一致的公开规格：总参 2.8T，激活 104B；<strong>93</strong> 层（含 1 层稠密）；注意力隐宽 7168，<strong>96</strong> 头；注意力层为 <strong>69 层 KDA + 24 层 Gated MLA</strong>；Latent MoE 维 3584，每专家隐宽 3072；<strong>896</strong> 路由专家、每 token 选 <strong>16</strong>、共享专家 <strong>2</strong>；激活为 SiTU-GLU；词表 160K；上下文 1048576。视觉编码器 <strong>MoonViT-V2</strong>，约 401M。权重从 SFT 起做量化感知训练：专家 <strong>MXFP4</strong>、激活 <strong>MXFP8</strong>。相对 K2 的 384 选 8 / 32B 激活，稀疏度与宽度都上了一个数量级；「A104B」是激活量，不是 104 个专家。</p><p><span class="marginnote">官方 API 价：缓存命中输入 0.30、未命中 3.00、输出 15.00 美元 / MTok。Mooncake 分离式推理在编码负载上宣称缓存命中率 90% 以上。推理力度启动时默认 max，low / high 随后补上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>KDA 提供近线性的长序列混合，周期性插入 Gated MLA 以保留全局交互。AttnRes 让一层可以<strong>按选择</strong>回看先前各层的表示，而不是把残差均匀累加。Stable LatentMoE 在 896 专家、top-16 的稀疏度下，用 Quantile Balancing 按路由分位数分配专家，去掉敏感的平衡超参；Per-Head Muon 按头独立优化注意力；SiTU 与 Gated MLA 分别管激活与选择性。报告把这些与数据配方合在一起，解释相对 K2 的 2.5× 标度效率。</p><p>预训练之后的后训练按域与推理力度分开做 RL（通用、智能体、编码），再经多教师 on-policy 蒸馏收成一套权重。环境覆盖可验证搜索与知识工作、软件工程与内核、带视觉闭环的前端 / CAD、持久助手与自主执行。轨迹常含成百上千次工具调用、累计百万上下文。</p>',12)),(e(),l(p,null,{default:o(()=>[m(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22%E9%A2%84%E8%AE%AD%E7%BB%83%203T%20%E7%BA%A7%20MoE%20%E5%BA%95%E5%BA%A7%22%5D%20--%3E%20KDA%5B%22KDA%20%E9%95%BF%E5%BA%8F%E5%88%97%20%2B%20%E5%91%A8%E6%9C%9F%20Gated%20MLA%22%5D%0A%20%20KDA%20--%3E%20AR%5B%22AttnRes%EF%BC%9A%E8%B7%A8%E5%B1%82%E5%9B%9E%E7%9C%8B%22%5D%0A%20%20AR%20--%3E%20MOE%5B%22Stable%20LatentMoE%EF%BC%9A896%20%E9%80%89%2016%22%5D%0A%20%20MOE%20--%3E%20RL%5B%22%E5%88%86%E5%9F%9F%20%2F%20%E5%88%86%20effort%20RL%22%5D%0A%20%20RL%20--%3E%20DIST%5B%22%E5%A4%9A%E6%95%99%E5%B8%88%20on-policy%20%E8%92%B8%E9%A6%8F%22%5D%0A%20%20DIST%20--%3E%20K3%5B%22Kimi%20K3%202.8T%20%2F%20104B%22%5D%0A%20%20VIT%5B%22MoonViT-V2%22%5D%20--%3E%20K3%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>基础设施与算法绑在一起：KDA 的融合核、上下文并行与感知状态的前缀缓存（并回馈 vLLM）；MoonEP 做静态形状、无主机同步关键路径的专家并行；百万 token 智能体 RL 用部分 rollout、外部 KV 保留、可恢复微虚拟机沙箱。部署建议 64 卡以上超节点，以便专家并行走高带宽域。</p><p><span class="marginnote">内核优化演示给模型最多 24 小时，在 Hopper 与另一家 GPGPU 上改 AttnRes / KDA / 512 头维 MLA。博客称 K3 可对标带 fallback 的 Fable 5，并明显超过当时对照的 Opus / GPT 档。评测脚注必须一起读：harness 混用 Kimi Code / Claude Code / Codex。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>KDA 把大部分层的序列混合从「每步全量 KV」换成线性递推，1M 窗口才可能按缓存命中价来卖；Gated MLA 周期出现，是为了不让线性核丢掉需要精确匹配的全局依赖。AttnRes 解决的是深度：超深 MoE 上均匀残差会把早期层的几何冲淡，选择性回看等于给信息一条捷径。Quantile Balancing 把负载从启发式 bias 改成分数分位数，稀疏度到 16/896 时这是训练能否继续的条件，而不只是吞吐优化。</p><p>思考历史必须整段回传。K3 在「保留思维」制度下训练；中途从别的模型切过来、或 harness 丢掉 reasoning 字段，质量会剧烈抖动。过度主动也是同一后训练的副作用：长程任务上模型会替用户做未授权决定，需要系统提示或 <code>AGENTS.md</code> 把边界写死。</p><h3 id="和-k2、和闭源旗舰" tabindex="-1">和 K2、和闭源旗舰 <a class="header-anchor" href="#和-k2、和闭源旗舰" aria-label="Permalink to &quot;和 K2、和闭源旗舰&quot;">​</a></h3><p>K2 无视觉、非思考评测、MuonClip、384 选 8。K3 有视觉、多档思考、KDA/AttnRes、896 选 16、1M 窗口。不要用 K2 的 SWE-Bench Verified 65.8 去要求 K3 的长程演示，也不要把 K3 博客里的芯片 / MiniTriton / 引力波案例当成可复现基准——那是案例研究。总体能力官方自己写：仍落后 Claude Fable 5 与 GPT-5.6 Sol，用户体验差距可感知。</p><h3 id="视觉进环不是外挂-vl-头" tabindex="-1">视觉进环不是外挂 VL 头 <a class="header-anchor" href="#视觉进环不是外挂-vl-头" aria-label="Permalink to &quot;视觉进环不是外挂 VL 头&quot;">​</a></h3><p>MoonViT-V2 约 401M，和语言 MoE 一起服务于「截图—改代码—再看」的闭环。游戏、前端、CAD 案例依赖这条路径；把 K3 当纯文本 API 用，等于关掉发布文里的一条主轴。OfficeQA Pro 把 PDF 整页当图、不给文字层，测的就是这条视觉+工具通道，而不是检索器质量。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>2.8T 权重不是「换成 Llama 配置就能服」。KDA 前缀缓存与普通 Transformer 不兼容，必须用已对齐的推理栈。许可是 <strong>Kimi K3 License</strong>，不是 Apache；再分发以当时文本为准。量化感知训练意味着官方检查点按 MXFP4/MXFP8 设计，乱转精度会先打路由。OfficeQA Pro 一类把 PDF 当图、不给文字层，测的是视觉+工具，不是纯检索。BrowseComp 在 1M 无压缩时博客报 90.4，带 300K 压缩策略是另一行——引用必须写管理策略。</p><p>不要编一份未公开的完整数据配比。报告与博客已经给出结构与系统；语料构成与去污染程序仍是读者需要自己判断的缺口。</p><p><span class="marginnote">出处：Kimi，<em>Kimi K3 Tech Blog</em>（2026-07-16）；Kimi Team，<em>Kimi K3: Open Frontier Intelligence</em>，arXiv:2607.24653；<code>MoonshotAI/Kimi-K3</code> 规格表。权重约 2026-07-27 放出。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kimi K3 是 2.8T / 104B 激活的原生多模态 MoE：896 专家 top-16、2 共享、69 KDA + 24 Gated MLA、1M 上下文。</li><li>结构主轴是 KDA、AttnRes 与 Stable LatentMoE；相对 K2 宣称约 2.5× 标度效率。</li><li>后训练按域与 effort 做 RL 再蒸馏；必须回传完整思维历史，并约束过度主动。</li><li>评测要钉 harness 与上下文管理；总体仍落后最强闭源旗舰。</li><li>出处：技术博客、arXiv:2607.24653、GitHub 模型卡。</li></ul>',15))])}const B=n(A,[["render",K]]);export{u as __pageData,B as default};
